<?php
session_start(); require_once('check-login.php'); require_once('website-content-utils.php');
if(!isset($_SESSION['ACCESSLEVEL']) || $_SESSION['ACCESSLEVEL'] !== 'administrator'){ http_response_code(403); exit('Only system administrators can manage announcements.'); }
if(empty($_SESSION['website_announcement_csrf'])){ $_SESSION['website_announcement_csrf'] = bin2hex(random_bytes(32)); }
website_announcements_ensure_table($con); $message=''; $tone='ok';
if($_SERVER['REQUEST_METHOD'] === 'POST'){
    if(!hash_equals($_SESSION['website_announcement_csrf'], isset($_POST['csrf']) ? $_POST['csrf'] : '')){ $message='Your form expired. Please try again.'; $tone='bad'; }
    elseif(isset($_POST['save_announcement'])){ $title=trim(isset($_POST['title']) ? $_POST['title'] : ''); $text=trim(isset($_POST['announcement_text']) ? $_POST['announcement_text'] : ''); if($title==='' || $text===''){ $message='Enter both a title and announcement text.'; $tone='bad'; } else { $stmt=mysqli_prepare($con,"INSERT INTO tblwebsiteannouncements (title, announcement_text, published_by) VALUES (?, ?, ?)"); $user=$_SESSION['USERID']; mysqli_stmt_bind_param($stmt,'sss',$title,$text,$user); $ok=mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); $message=$ok?'Announcement published. It is now visible to the public.':'The announcement could not be published.'; if(!$ok){$tone='bad';} } }
    elseif(isset($_POST['toggle_id'])){ $id=(int)$_POST['toggle_id']; $status=$_POST['new_status']==='hidden'?'hidden':'published'; $stmt=mysqli_prepare($con,'UPDATE tblwebsiteannouncements SET status=? WHERE announcement_id=?'); mysqli_stmt_bind_param($stmt,'si',$status,$id); $ok=mysqli_stmt_execute($stmt); mysqli_stmt_close($stmt); $message=$ok?'Announcement updated.':'The announcement could not be updated.'; if(!$ok){$tone='bad';} }
}
$announcements=website_announcements($con,true);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Announcements | AYISEC</title><link rel="stylesheet" href="css/font-awesome-4.7.0/css/font-awesome.min.css"><style>body{margin:0;background:#f3f6f8;color:#15283b;font:16px/1.5 Arial,sans-serif}.wrap{max-width:1000px;margin:38px auto;padding:0 20px}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}h1,h2{margin:0 0 8px}.top a,.button{display:inline-block;padding:10px 15px;border:0;border-radius:7px;background:#0f4c75;color:#fff;text-decoration:none;font-weight:bold;cursor:pointer}.back{background:#fff!important;color:#183650!important;border:1px solid #d7e0e8!important}.card{background:#fff;border:1px solid #dce5eb;border-radius:10px;padding:24px;margin-bottom:20px}.msg{padding:13px 16px;border-radius:7px;margin-bottom:18px}.ok{background:#dcfce7;color:#166534}.bad{background:#fee2e2;color:#991b1b}label{display:block;font-weight:bold;margin:14px 0 6px}input,textarea{box-sizing:border-box;width:100%;padding:10px;border:1px solid #becbd5;border-radius:6px;font:inherit}textarea{min-height:150px;resize:vertical}.entry{border-bottom:1px solid #dce5eb;padding:18px 0}.entry:last-child{border:0}.entry h3{margin:0 0 3px}.meta{font-size:13px;color:#64748b}.hidden{color:#b45309}.hide{background:#b45309!important}.show{background:#15803d!important}@media(max-width:600px){.top{align-items:flex-start;flex-direction:column}}</style></head><body><main class="wrap"><div class="top"><div><h1>Manage Announcements</h1><p>Publish school notices for visitors and keep earlier notices in the archive.</p></div><div><a class="back" href="website-editor.php">Website editor</a> <a href="announcements.php" target="_blank">View public archive</a></div></div><?php if($message!==''){ ?><div class="msg <?php echo website_content_escape($tone); ?>"><?php echo website_content_escape($message); ?></div><?php } ?><section class="card"><h2>New announcement</h2><form method="post"><input type="hidden" name="csrf" value="<?php echo website_content_escape($_SESSION['website_announcement_csrf']); ?>"><label>Title</label><input name="title" maxlength="180" required placeholder="e.g. Reopening date for students"><label>Announcement</label><textarea name="announcement_text" maxlength="5000" required></textarea><button class="button" name="save_announcement" type="submit"><i class="fa fa-bullhorn"></i> Publish announcement</button></form></section><section class="card"><h2>Published and previous announcements</h2><?php if(empty($announcements)){ ?><p>No announcements have been published yet.</p><?php } foreach($announcements as $announcement){ ?><article class="entry"><h3><?php echo website_content_escape($announcement['title']); ?></h3><div class="meta"><?php echo website_content_escape(date('d M Y, g:i a',strtotime($announcement['published_at']))); ?> · <span class="<?php echo $announcement['status']==='hidden'?'hidden':''; ?>"><?php echo website_content_escape(ucfirst($announcement['status'])); ?></span></div><p><?php echo nl2br(website_content_escape($announcement['announcement_text'])); ?></p><form method="post"><input type="hidden" name="csrf" value="<?php echo website_content_escape($_SESSION['website_announcement_csrf']); ?>"><input type="hidden" name="toggle_id" value="<?php echo (int)$announcement['announcement_id']; ?>"><input type="hidden" name="new_status" value="<?php echo $announcement['status']==='published'?'hidden':'published'; ?>"><button class="button <?php echo $announcement['status']==='published'?'hide':'show'; ?>" type="submit"><?php echo $announcement['status']==='published'?'Hide from public':'Publish again'; ?></button></form></article><?php } ?></section></main></body></html>
